namespace sv_650ab22b82f343158e1fc4c94b4d7de7.Models;

public class Recipe
{
    public int Id { get; set; }
    public required string Title { get; set; }
    public required string Description { get; set; }
    public int PrepTimeMinutes { get; set; }
}

using sv_650ab22b82f343158e1fc4c94b4d7de7.Models;

namespace sv_650ab22b82f343158e1fc4c94b4d7de7.Services;

public class RecipeService
{
    private static readonly Dictionary<int, List<Recipe>> RecipesByCuisine = new()
    {
        [1] = new List<Recipe>
        {
            new() { Id = 1, Title = "Margherita Pizza", Description = "Classic pizza with tomato, mozzarella, and basil.", PrepTimeMinutes = 30 },
            new() { Id = 2, Title = "Spaghetti Carbonara", Description = "Creamy pasta with pancetta, egg, and parmesan.", PrepTimeMinutes = 25 },
            new() { Id = 3, Title = "Bruschetta", Description = "Toasted bread topped with tomatoes, garlic, and olive oil.", PrepTimeMinutes = 15 },
        },
        [2] = new List<Recipe>
        {
            new() { Id = 4, Title = "Chicken Tikka Masala", Description = "Tender chicken in a rich, spiced tomato-cream sauce.", PrepTimeMinutes = 45 },
            new() { Id = 5, Title = "Palak Paneer", Description = "Creamy spinach curry with soft paneer cheese.", PrepTimeMinutes = 35 },
            new() { Id = 6, Title = "Samosa", Description = "Crispy pastry filled with spiced potatoes and peas.", PrepTimeMinutes = 50 },
        },
        [3] = new List<Recipe>
        {
            new() { Id = 7, Title = "Sushi Rolls", Description = "Vinegared rice with fresh fish and vegetables wrapped in nori.", PrepTimeMinutes = 40 },
            new() { Id = 8, Title = "Ramen", Description = "Rich pork bone broth with noodles, egg, and chashu.", PrepTimeMinutes = 60 },
            new() { Id = 9, Title = "Tempura", Description = "Lightly battered and deep-fried shrimp and vegetables.", PrepTimeMinutes = 25 },
        },
    };

    public async Task<List<Recipe>> GetByCuisineAsync(int cuisineId, CancellationToken cancellationToken)
    {
        await Task.Delay(2000, cancellationToken);

        if (RecipesByCuisine.TryGetValue(cuisineId, out var recipes))
        {
            return recipes;
        }

        return [];
    }
}

@page "/recipes/{CuisineId:int}"
@rendermode InteractiveServer
@implements IAsyncDisposable
@inject RecipeService RecipeService
@inject ILogger<Recipes> Logger

<PageTitle>Recipes</PageTitle>

<h1>Recipes</h1>

@if (error is not null)
{
    <div class="alert alert-danger">
        <p>@error</p>
        <button class="btn btn-outline-danger btn-sm" @onclick="LoadAsync">Retry</button>
    </div>
}
else if (recipes is null)
{
    <p><em>Loading recipes…</em></p>
}
else
{
    @if (isLoading)
    {
        <p><em>Refreshing…</em></p>
    }

    @{
        var displayed = sort == "popular"
            ? recipes.OrderBy(r => r.PrepTimeMinutes).ToList()
            : recipes.OrderByDescending(r => r.Id).ToList();
    }

    <table class="table">
        <thead>
            <tr>
                <th>Title</th>
                <th>Description</th>
                <th>Prep Time (min)</th>
            </tr>
        </thead>
        <tbody>
            @foreach (var recipe in displayed)
            {
                <tr>
                    <td>@recipe.Title</td>
                    <td>@recipe.Description</td>
                    <td>@recipe.PrepTimeMinutes</td>
                </tr>
            }
        </tbody>
    </table>
}

@code {
    [Parameter] public int CuisineId { get; set; }
    [SupplyParameterFromQuery(Name = "sort")] public string? Sort { get; set; }

    private CancellationTokenSource? cts;
    private int? loadedCuisineId;
    private List<Recipe>? recipes;
    private string? sort;
    private bool isLoading;
    private string? error;

    protected override async Task OnParametersSetAsync()
    {
        sort = Sort;

        if (CuisineId == loadedCuisineId)
        {
            return;
        }

        loadedCuisineId = CuisineId;
        await LoadAsync();
    }

    private async Task LoadAsync()
    {
        if (cts is not null)
        {
            await cts.CancelAsync();
            cts.Dispose();
        }

        cts = new CancellationTokenSource();
        var cancellationToken = cts.Token;

        error = null;
        isLoading = true;

        try
        {
            var result = await RecipeService.GetByCuisineAsync(CuisineId, cancellationToken);
            recipes = result;
        }
        catch (OperationCanceledException) when (cancellationToken.IsCancellationRequested)
        {
            // Self-cancellation (parameter change or disposal) — let ComponentBase handle it.
            throw;
        }
        catch (OperationCanceledException ex)
        {
            Logger.LogWarning(ex, "Request timed out loading recipes for cuisine {CuisineId}", CuisineId);
            error = "The request timed out. Please try again.";
        }
        catch (Exception ex)
        {
            Logger.LogError(ex, "Failed to load recipes for cuisine {CuisineId}", CuisineId);
            error = "Unable to load recipes. Please try again.";
        }
        finally
        {
            isLoading = false;
        }
    }

    public async ValueTask DisposeAsync()
    {
        if (cts is not null)
        {
            await cts.CancelAsync();
            cts.Dispose();
        }
    }
}

